import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百三十四章 沉重的负担","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/234第二百三十四章 沉重的负担-五取蕴为负担.md","filePath":"meditation/巴利文大藏经/234第二百三十四章 沉重的负担-五取蕴为负担.md"}'),o={name:"meditation/巴利文大藏经/234第二百三十四章 沉重的负担-五取蕴为负担.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第二百三十四章-沉重的负担" tabindex="-1">第二百三十四章 沉重的负担 <a class="header-anchor" href="#第二百三十四章-沉重的负担" aria-label="Permalink to &quot;第二百三十四章 沉重的负担&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>3.负担品</p><p>相应部22相应22经/负担经(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！如来将要为你们讲说：什么是重担？什么是挑担者？什么是取担？什么是舍担？你们要认真的听，你们要仔细的思考。如来要开始说法了。”</p><p>出家弟子们回答：“世尊，我们会认真听您说法的，我们会仔细的思考的，恭请世尊您为我们说法。”</p><p>佛陀说：“比丘们！什么是重担呢？重担就是「五取蕴」，「五取蕴」就是：色取蕴、受取蕴、想取蕴、行取蕴、识取蕴。由物质事物、物质身体生起的烦恼就称为「色取蕴」，由感受生起的烦恼就称为「受取蕴」，由念想生起的烦恼就称为「想取蕴」，由行为生起的烦恼就称为「行取蕴」，由认识、分别、判断生起的烦恼就称为「识取蕴」。比丘们！这就是重担，这就是负担。</p><p>比丘们！那谁是挑重担的人呢？谁是挑担人呢？就是世间这个由各种条件生起的自认为是我的人，为什么这么说呢？因为这个自认为是我的人，无法永远的在世间存在，他错认为自己是永恒不变的我，错认为自己是有主宰权的、真实不变的我。他的这个我不过是假名叫我而已，因为他一旦死亡，这个所谓的假我就不存在了。比丘们！这个所谓的我就是挑重担的人，这个假我就是挑担人。</p><p>比丘们！什么是取担？什么是拿起负担呢？就是对物质事物、物质身体、感受、念想、行为、认识、分别、判断多次、无数次的生起快乐、贪求、渴爱、贪爱这就是取担、拿起负担。也就是：对欲望的渴爱，对存在、生存、获得的渴爱，对永远解脱生死的渴爱，对不生不灭涅槃境界的渴爱，比丘们！这就是取担，这个就是拿起负担。</p><p>比丘们！什么是舍担？什么是放下负担？就是逐渐除灭、灭尽、舍弃、断除对物质事物、物质身体、感受、念想、行为、认识、分别、判断的渴爱、贪爱。不再对物质事物、物质身体、感受、念想、行为、认识、分别、判断生起渴爱、贪爱，不会再执着和挂念这些渴爱、贪爱，不会再被这些渴爱、贪爱束缚捆绑，从这些渴爱、贪爱中彻底的解脱出来。比丘们！这就是舍担、放下负担。</p><p>物质事物、物质身体、感受、念想、行为、认识、分别、判断就是沉重的负担，挑起这个沉重负担的人就是一个暂时取名叫「我」的人，这个「我」无法永远在世间存在，所以他不是有主宰权、真实不变的「我」。世间众生烦恼和痛苦的产生就是因为他们要去拿起负担，他们一旦对物质事物、物质身体、感受、念想、行为、认识、分别、判断生起快乐、贪求、渴爱、贪爱。那他们就是拿起了负担，他们就会最终产生烦恼和痛苦。</p><p>只要世间的众生他们放下负担，他们除灭、灭尽、舍弃、断除对物质事物、物质身体、感受、念想、行为、认识、分别、判断的渴爱、贪爱。彻底的根除掉对世间一切事物的渴爱、贪爱，那么他们就是放下了负担。当他们放下负担的时候，他们就能让自己清净安宁，他们就能除灭自己的烦恼和痛苦。当他们放下所有的负担，不再去拿起任何负担的时候，当他们彻底根除掉所有的渴爱、贪爱的时候，他们就能除灭、灭尽自己一切的烦恼和痛苦，他们就能到达没有欲望、没有烦恼和痛苦的涅槃境界。”</p><p>这时，佛陀说偈言：</p><p>「重担是五蕴，</p><p>担者名为我。</p><p>世间取担苦，</p><p>舍担为安宁。</p><p>已舍重担者，</p><p>不再取重担。</p><p>根绝渴爱者，</p><p>无欲般涅槃。」</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',22)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
